import fs from "node:fs/promises";
import path from "node:path";
import type { SessionStore, StoredSession } from "./sessions.js";

// Ids are generated by us, so anything else on disk is not ours and must never reach a file path.
const ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

function isStored(value: unknown): value is StoredSession {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    ID.test(v.id) &&
    typeof v.model === "string" &&
    typeof v.device === "string" &&
    typeof v.root === "string" &&
    typeof v.created === "number" &&
    Array.isArray(v.history) &&
    Array.isArray(v.events)
  );
}

// One JSON file per session. Conversations can contain file contents, so files are private to the owner.
export function fileStore(dir: string): SessionStore {
  const file = (id: string): string => {
    if (!ID.test(id)) throw new Error("invalid session id");
    return path.join(dir, `${id}.json`);
  };
  // Saves for one session are queued so a slow write cannot overwrite a newer one.
  const queues = new Map<string, Promise<unknown>>();

  return {
    save(session) {
      const run = (queues.get(session.id) ?? Promise.resolve()).catch(() => undefined).then(async () => {
        await fs.mkdir(dir, { recursive: true, mode: 0o700 });
        const target = file(session.id);
        const tmp = `${target}.${process.pid}.tmp`;
        await fs.writeFile(tmp, JSON.stringify(session), { mode: 0o600 });
        // On Windows a rename onto a file that is open elsewhere briefly fails; try again before giving up.
        for (let attempt = 0; ; attempt++) {
          try {
            await fs.rename(tmp, target);
            return;
          } catch (err) {
            const code = (err as NodeJS.ErrnoException).code;
            if (attempt >= 5 || (code !== "EPERM" && code !== "EBUSY" && code !== "EACCES")) {
              await fs.rm(tmp, { force: true });
              throw err;
            }
            await new Promise((r) => setTimeout(r, 20 * (attempt + 1)));
          }
        }
      });
      queues.set(session.id, run);
      return run;
    },
    async remove(id) {
      await queues.get(id)?.catch(() => undefined);
      await fs.rm(file(id), { force: true });
    },
  };
}

// Reads every stored session. Files that are not valid sessions are skipped, with a warning.
export async function loadStored(dir: string, warn: (message: string) => void = console.warn): Promise<StoredSession[]> {
  let names: string[];
  try {
    names = await fs.readdir(dir);
  } catch {
    return [];
  }
  const out: StoredSession[] = [];
  for (const name of names) {
    if (!name.endsWith(".json")) continue;
    try {
      const parsed: unknown = JSON.parse(await fs.readFile(path.join(dir, name), "utf8"));
      if (!isStored(parsed) || `${parsed.id}.json` !== name) throw new Error("not a stored session");
      out.push(parsed);
    } catch (err) {
      warn(`[gateway] skipping ${name}: ${(err as Error).message}`);
    }
  }
  return out;
}
